/* OOL UI stays scoped to its inventory view and own dialogs. */
window.OOL = (() => {
  let root, state, tab='list', page=1, selected=new Set(), expanded=new Set(), search='', filters={}, loading=false, savedSnapshot=false, activeCalls=0, stateUser='';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>(n/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const sum=(rows,key)=>rows.reduce((n,x)=>n+(x[key]||0),0);
  const uuid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');
  const badgeColors={
    'Awaiting OC':'awaiting-oc',
    'Order Confirmed':'oc-confirmed',
    'Delivery Confirmed':'delivery-confirmed',
    'Partially Requested':'partially-requested',
    'Partially Confirmed':'partially-confirmed',
    'Delivery Requested':'delivery-requested',
    'Delivered':'delivered',
    'Cancelled':'cancelled'
  };
  const statusDetailOrder=['Delivery Requested','Delivery Confirmed','Available','Delivered'];
  const badge=(s,details=[],showDetails=false)=>{const hint=/Partial/.test(s)||showDetails?details.filter(([n])=>n>0).sort((a,b)=>statusDetailOrder.indexOf(a[1])-statusDetailOrder.indexOf(b[1])).map(([n,label])=>`${n} ${label}`).join('\n'):'';return `<span class="ool-badge ${badgeColors[s]||'cancelled'}" ${hint?`tabindex="0" data-status-details="${esc(hint)}" aria-label="${esc(s+': '+hint.replaceAll('\n',', '))}"`:''}>${esc(s)}</span>`;};
  const hasMultipleDeliveryRequests=lineId=>state.requests.filter(r=>!r.deletedAt&&r.lines.some(l=>l.lineId===lineId&&l.qty-(l.cancelled||0)>requestReceived(l))).length>1;
  const requestDetails=r=>{const received=sum(state.receipts.flatMap(x=>x.allocations).filter(a=>r.lines.some(l=>l.id===a.requestLineId)),'qty');return [[Math.max(0,sum(r.lines,'confirmed')-received),'Delivery Confirmed'],[sum(r.lines,'qty')-sum(r.lines,'confirmed')-sum(r.lines,'cancelled'),'Delivery Requested'],[received,'Delivered']];};
  function hideStatusTooltip(){document.querySelector('[aria-describedby="ool-status-tooltip"]')?.removeAttribute('aria-describedby');document.getElementById('ool-status-tooltip')?.remove();}
  function showStatusTooltip(b){hideStatusTooltip();const tip=document.createElement('div');tip.id='ool-status-tooltip';tip.className='ool-status-tooltip';tip.setAttribute('role','tooltip');tip.textContent=b.dataset.statusDetails;document.body.append(tip);b.setAttribute('aria-describedby',tip.id);const rect=b.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(rect.right-tip.offsetWidth,innerWidth-tip.offsetWidth-8))+'px';tip.style.top=(rect.bottom+tip.offsetHeight+14<innerHeight?rect.bottom+7:Math.max(8,rect.top-tip.offsetHeight-7))+'px';}
  function bindStatusTooltips(){root.onmouseover=e=>{const b=e.target.closest('[data-status-details]');if(b&&!b.contains(e.relatedTarget))showStatusTooltip(b);};root.onmouseout=e=>{const b=e.target.closest('[data-status-details]');if(b&&!b.contains(e.relatedTarget))hideStatusTooltip();};root.onfocusin=e=>{const b=e.target.closest('[data-status-details]');if(b)showStatusTooltip(b);};root.onfocusout=hideStatusTooltip;root.onkeydown=e=>{if(e.key==='Escape')hideStatusTooltip();};}
  window.addEventListener('scroll',()=>{const b=root?.querySelector('[data-status-details]:hover');if(b)showStatusTooltip(b);else hideStatusTooltip();},true);
  window.addEventListener('resize',hideStatusTooltip);
  document.addEventListener('pointerdown',hideStatusTooltip);
  const icon=(n)=>`<img src="/assets/maintenance-icons/${n}.svg" alt="">`;
  const admin=()=>typeof currentUser!=='undefined'&&String(currentUser?.role).toLowerCase()==='admin';
  function showProgress(label){const node=document.getElementById('oolSyncStatus');if(node){node.textContent=label||'';node.hidden=!label;}}
  async function busy(button,label,fn){if(button?.disabled)return;const html=button?.innerHTML;if(button){button.disabled=true;button.setAttribute('aria-busy','true');button.classList.add('ool-busy');button.textContent=label;}try{return await fn();}finally{if(button?.isConnected){button.disabled=false;button.innerHTML=html;button.removeAttribute('aria-busy');button.classList.remove('ool-busy');}}}
  async function call(action='',body){activeCalls++;showProgress(body?'Saving changes…':'Updating OOL…');try{const r=await fetch('/api/ool'+(action?'/'+action:''),{...(body?{method:'POST',body:JSON.stringify({...body,revision:state?.revision})}:{}),headers:{'X-OOL-View':'compact',...(body?{'Content-Type':'application/json'}:{})}});const data=await r.json();if(!r.ok)throw Error(data.error||'OOL could not be saved');if(!body&&data.revision<state?.revision)return state;if(body&&data.lines&&data.requests&&data.receipts){state={...state,...data};savedSnapshot=true;}else if(!body)savedSnapshot=false;return data;}finally{activeCalls--;if(!activeCalls)showProgress('');}}
  function fail(e){if(typeof toast==='function')toast(e.message);else alert(e.message);}
  async function refresh(force=false){if(force||!savedSnapshot)state=await call();savedSnapshot=false;document.querySelectorAll('#viewActions .ool-header-actions button,#viewActions .ool-header-actions input').forEach(control=>{control.disabled=false;});if(root?.isConnected)render();}
  function headerActions(){const actions=document.querySelector('#viewActions');if(!actions)return;actions.classList.remove('hidden');actions.innerHTML=`<div class="ool-header-actions"><span id="oolSyncStatus" class="ool-sync-status" role="status" aria-live="polite" hidden></span><input id="oolSearch" aria-label="Search OOL" placeholder="Search SOR, PO, Project or Model…" value="${esc(search)}"><details><summary aria-label="More OOL actions" title="More OOL actions"><img src="/assets/dx-icons/ellipsis-vertical.svg" alt=""></summary><div><button data-ool="oc">+ Add OC</button><button data-ool="receipts">Match received materials</button>${admin()?'<button data-ool="import">Import / reconcile Excel</button><button data-ool="audit">Recent Activity</button>':''}<button data-ool="refresh">Refresh balances</button></div></details></div>`;actions.querySelectorAll('button,input').forEach(control=>{control.disabled=!state;});actions.querySelector('#oolSearch').oninput=e=>{search=e.target.value;page=1;render();};actions.querySelectorAll('[data-ool]').forEach(button=>button.onclick=async()=>{button.closest('details')?.removeAttribute('open');try{const a=button.dataset.ool;if(a==='oc')openOC();if(a==='receipts')receiptDialog();if(a==='import')importDialog();if(a==='audit')auditDialog();if(a==='refresh')await refresh(true);}catch(err){fail(err);}});}
  async function mount(el){root=el;if(stateUser!==currentUser?.id){state=undefined;savedSnapshot=false;selected.clear();stateUser=currentUser?.id;} if(!['admin','staff'].includes(String(currentUser?.role).toLowerCase())){root.innerHTML='<div class="ool-empty">OOL is available to Admin and Staff only.</div>';return;}headerActions();
    if(state)render();else root.innerHTML='<div class="ool-loading-shell" aria-busy="true"><div class="ool-loading-kpis">'+Array.from({length:5},()=>'<div class="ool-skeleton"></div>').join('')+'</div><div class="ool-skeleton ool-loading-table"><span class="ool-sync-status">Loading OOL balances…</span></div></div>';if(loading)return;loading=true;try{await refresh(true);}catch(e){root.innerHTML='<div class="ool-empty">Unable to load OOL. <button data-ool="refresh">Retry</button></div>';root.onclick=()=>mount(root);fail(e);}finally{loading=false;}}
  const status=r=>{const q=sum(r.lines,'qty')-sum(r.lines,'cancelled'),c=sum(r.lines,'confirmed');const received=state.receipts.flatMap(x=>x.allocations).filter(a=>r.lines.some(l=>l.id===a.requestLineId)).reduce((n,x)=>n+x.qty,0);return !q?'Cancelled':received===q?'Delivered':c===q?'Delivery Confirmed':c?'Partially Confirmed':'Delivery Requested';};
  function filtered(){return state.lines.filter(l=>(!filters.status||l.status===filters.status)&&(!filters.poNo||l.poNo===filters.poNo)&&(!filters.sor||l.sor===filters.sor)&&(l.remaining||l.confirmedQty<l.orderQty)&&[l.sd,l.sor,l.poNo,l.project,l.model].join(' ').toLowerCase().includes(search.toLowerCase()));}
  function statusFilter(){const opts=tab==='list'?Object.keys(badgeColors).filter(s=>!['Partially Confirmed','Cancelled'].includes(s)):['Delivery Requested','Partially Confirmed','Delivery Confirmed','Delivered','Cancelled'];return `<label>Status<select data-filter="status"><option value="">All statuses</option>${opts.map(s=>`<option ${filters.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`;}
  function dropdown(key,label){const opts=[...new Set(state.lines.map(l=>l[key]).filter(Boolean))].sort();return `<label>${label}<select data-filter="${key}"><option value="">All ${label==='PO No.'?'POs':label==='SOR No.'?'SORs':'Projects'}</option>${opts.map(x=>`<option ${filters[key]===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;}
  function oolLineStatusHtml(l){const html=badge(l.status,[[l.deliveryConfirmed,'Delivery Confirmed'],[l.requested,'Delivery Requested'],[l.available,'Available'],[l.received,'Delivered']],hasMultipleDeliveryRequests(l.id));return l.confirmedQty<l.orderQty?`<button type="button" class="ool-status-action" data-confirm="${esc(l.poId||l.id)}" title="Add or verify OC" aria-label="${esc(l.status)} — add or verify OC">${html}</button>`:html;}
  function listTableHTML(rows){
    const widths=[3,8,10,17,16,5,5,7,7,7,8,7];
    const headings=['','SOR / SD','PO No.','Project','Model','Order<br>Qty','Rq<br>Qty','Delivered<br>Qty','Available<br>Qty','Unit Price (AED)','Amount (AED)','Status'];
    return `<table class="ool-table ool-list-table"><colgroup>${widths.map(width=>`<col style="width:${width}%">`).join('')}</colgroup><thead><tr><th><input type="checkbox" id="oolSelectAll" aria-label="Select all filtered selectable materials"></th>${headings.slice(1).map(heading=>`<th>${heading}</th>`).join('')}</tr></thead><tbody>${rows.slice((page-1)*25,page*25).map(l=>`
      <tr class="${selected.has(l.id)?'selected':''}">
        <td><input type="checkbox" data-select="${esc(l.id)}" ${selected.has(l.id)?'checked':''} ${!l.available&&l.status!=='Awaiting OC'?'disabled':''} aria-label="Select ${esc(l.model)}"></td>
        <td><strong>${esc(l.sor||'—')}</strong><small>${esc(l.sd||'—')}</small></td>
        <td class="ool-po-cell"><div class="ool-po-number" title="${esc(l.poNo)}">${l.poId?`<button class="ool-link" data-po="${esc(l.poId)}">${esc(l.poNo)}</button>`:`<span>${esc(l.poNo)}</span>`}</div></td>
        <td class="ool-project-cell"><input class="ool-project-input" data-project-inline="${esc(l.id)}" aria-label="Project" title="${esc(l.project)}" value="${esc(l.project)}"></td>
        <td class="ool-model-cell"><strong class="ool-model-name" title="${esc(l.model)}">${esc(l.model)}</strong></td>
        <td>${l.orderQty}${l.confirmedQty<l.orderQty?`<small>${l.confirmedQty} OC</small>`:''}</td>
        <td title="Requested quantities awaiting confirmation or receipt">${l.requested+l.deliveryConfirmed}</td><td>${l.received}</td><td><b class="ool-qty ${l.available===0?'ool-qty-zero':''}">${l.available}</b></td>
        <td class="ool-number">${money(l.priceCents)}</td><td class="ool-number"><b>${money(l.amountCents)}</b></td>
        <td>${oolLineStatusHtml(l)}</td>
      </tr>`).join('')||'<tr><td colspan="12" class="ool-empty">No materials match your filters.</td></tr>'}</tbody></table>`;
  }
  function render(){hideStatusTooltip();if(!root?.isConnected)return;const k=state.kpis; const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/25));if(tab==='list')page=Math.min(page,pages);const chosen=state.lines.filter(l=>selected.has(l.id)&&(l.available>0||l.status==='Awaiting OC'));
    root.innerHTML=`<div class="ool">
    <div class="ool-kpis">${[['package','Total OOL Qty',k.total,'Units','blue'],['database','Total OOL Value','AED '+money(k.valueCents),'Excluding VAT','green'],['truck','Requested Qty',k.requested,'Awaiting delivery confirmation','amber'],['circle-check','Delivery Confirmed Qty',k.confirmed,'Awaiting receipt','green'],['box','Available Qty',k.available,'Ready to request','blue']].map(([i,t,v,s,c])=>`<div class="ool-kpi ${c}"><span class="ool-kpi-icon">${icon(i)}</span><div><span>${t}</span><strong>${v}</strong><small>${s}</small></div></div>`).join('')}</div>
    <div class="ool-controls"><div class="ool-tabs"><button data-tab="list" class="${tab==='list'?'active':''}">${icon('package')} OOL List <span>${rows.length}</span></button><button data-tab="requests" class="${tab==='requests'?'active':''}">${icon('send')} Delivery Requests <span>${state.requests.filter(r=>!r.deletedAt).length}</span></button><button data-tab="delivered" class="${tab==='delivered'?'active':''}">${icon('circle-check')} Delivered List <span>${deliveredRows().length}</span></button></div>
    <div class="ool-filters">${dropdown('poNo','PO No.')}${dropdown('sor','SOR No.')}${tab==='delivered'?'':statusFilter()}</div></div>
    ${tab==='list'?`<div class="ool-card">${chosen.length?`<div class="ool-selection"><strong>${chosen.length} ${chosen.length===1?'model':'models'} selected</strong><button type="button" class="ool-delete-selected" data-ool="delete-lines" aria-label="Delete selected OOL materials" title="Delete selected OOL materials" ${chosen.every(l=>['Awaiting OC','Order Confirmed'].includes(l.status)&&!l.received)?'':'disabled'}>${icon('trash-2')}</button><span>Total Qty: <b>${sum(chosen,'available')}</b> &nbsp; | &nbsp; AED <b>${money(chosen.reduce((n,l)=>n+l.available*l.priceCents,0))}</b></span><button class="ool-primary" data-ool="request" ${chosen.some(l=>l.available>0)?'':'disabled'}>${icon('send')} Request Delivery</button></div>`:''}<div class="ool-table-wrap">${listTableHTML(rows)}</div><div class="ool-footer"><span>${rows.length?`${(page-1)*25+1}–${Math.min(page*25,rows.length)} of ${rows.length} materials`:'0 materials'}</span><span>Total OOL Qty: <b>${sum(rows,'remaining')}</b> &nbsp; | &nbsp; AED <b>${money(sum(rows,'amountCents'))}</b></span><div><button data-page="${page-1}" ${page<=1?'disabled':''}>‹</button> ${page} / ${pages} <button data-page="${page+1}" ${page>=pages?'disabled':''}>›</button></div></div></div>`:tab==='delivered'?deliveredHTML():requestsHTML()}
    <p class="ool-note">Balances exclude received materials. Awaiting OC quantities are listed for tracking and excluded from available stock and OOL value.</p></div>`;
    root.querySelectorAll('.ool-list-table .ool-model-name').forEach(model=>{if(model.scrollWidth<=model.clientWidth)model.removeAttribute('title');});
    bind();
  }
  function deliveredRows(){
    const grouped=new Map(),sources=new Map((state.sources||[]).map(s=>[s.id,s])),lines=new Map(state.lines.map(l=>[l.id,l])),requests=new Map(state.requests.flatMap(r=>r.lines).map(l=>[l.id,l]));
    for(const receipt of state.receipts)for(const a of receipt.allocations){
      if(!(a.qty>0))continue;
      const material=lines.get(a.lineId);if(!material)continue;
      const source=sources.get(receipt.sourceId),request=requests.get(a.requestLineId),key=[receipt.sourceId,a.sourceIndex??'',a.lineId].join('|');
      if(!grouped.has(key))grouped.set(key,{id:key,sor:request?.sor||material.sor||'',sd:request?.sd||material.sd||'',dnNo:receipt.dnNo||source?.dnNo||receipt.sourceLabel||'',date:receipt.dnDate||source?.date||'',downloadUrl:source?.downloadUrl||'',downloadName:source?.downloadName||'',project:String(receipt.sourceId||'').startsWith('direct:')?(source?.projectName||receipt.projectName||material.project||request?.project||''):(material.project||request?.project||''),poNo:request?.poNo||material.poNo||'',model:material.model,qty:0,recordedAt:receipt.date||''});
      const row=grouped.get(key);row.qty+=a.qty;if((receipt.date||'')>row.recordedAt)row.recordedAt=receipt.date;
    }
    const dateKey=value=>{const m=String(value).match(/^(\d{2})[/-](\d{2})[/-](\d{4})$/);return m?`${m[3]}-${m[2]}-${m[1]}`:String(value).slice(0,10);};
    return [...grouped.values()].sort((a,b)=>b.recordedAt.localeCompare(a.recordedAt)||dateKey(b.date).localeCompare(dateKey(a.date))||a.model.localeCompare(b.model));
  }
  function deliveredHTML(){
    const rows=deliveredRows().filter(l=>(!filters.poNo||l.poNo===filters.poNo)&&(!filters.sor||l.sor===filters.sor)&&[l.sor,l.sd,l.dnNo,l.project,l.poNo,l.model].join(' ').toLowerCase().includes(search.toLowerCase()));
    const pages=Math.max(1,Math.ceil(rows.length/25));page=Math.min(page,pages);
    const dateLabel=value=>{if(!value)return 'Date not recorded';const iso=String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);return iso?`${iso[3]}/${iso[2]}/${iso[1]}`:String(value);};
    return `<div class="ool-card"><div class="ool-table-wrap"><table class="ool-table ool-delivered-table"><colgroup><col style="width:19%"><col style="width:22%"><col style="width:29%"><col style="width:22%"><col style="width:8%"></colgroup><thead><tr><th>SOR / SD Document</th><th>DN No. / Date</th><th>Project / PO No.</th><th>Model</th><th>Qty</th></tr></thead><tbody>${rows.slice((page-1)*25,page*25).map(l=>`<tr><td><strong>${esc(l.sor||'Not recorded')}</strong><small>${esc(l.sd||'Not recorded')}</small></td><td>${l.downloadUrl?`<a class="ool-delivery-note-link" href="${esc(l.downloadUrl)}" download="${esc(l.downloadName||l.dnNo||'Delivery-note')}" title="Download delivery note"><strong>${esc(l.dnNo||'Delivery note')}</strong></a>`:`<strong title="No delivery note file uploaded">${esc(l.dnNo||'Not recorded')}</strong>`}<small>${esc(dateLabel(l.date))}</small></td><td><strong>${esc(l.project||'—')}</strong><small>${esc(l.poNo||'Not recorded')}</small></td><td><strong>${esc(l.model)}</strong></td><td><b class="ool-qty">${l.qty}</b></td></tr>`).join('')||'<tr><td colspan="5" class="ool-empty">No delivered OOL materials match your filters.</td></tr>'}</tbody></table></div><div class="ool-footer"><span>${rows.length?`${(page-1)*25+1}–${Math.min(page*25,rows.length)} of ${rows.length} delivered materials`:'0 delivered materials'}</span><span>Total Delivered Qty: <b>${sum(rows,'qty')}</b></span><div><button data-page="${page-1}" ${page<=1?'disabled':''}>‹</button> ${page} / ${pages} <button data-page="${page+1}" ${page>=pages?'disabled':''}>›</button></div></div></div>`;
  }
  const activeRequestLines=r=>r.lines.filter(l=>l.qty-(l.cancelled||0)>0);
  const requestReceived=l=>sum(state.receipts.flatMap(x=>x.allocations).filter(a=>a.requestLineId===l.id),'qty');
  function deleteButton(r,l){
    const eligible=l?l.qty-l.confirmed-(l.cancelled||0)>0:r.lines.every(x=>x.confirmed===0&&requestReceived(x)===0);
    if(!eligible)return '';
    const label=l?(l.confirmed?'Remove pending quantity':'Delete requested material'):'Delete delivery request';
    return `<button type="button" class="ool-delete-x" data-delete-request="${esc(r.id)}" ${l?`data-delete-line="${esc(l.id)}"`:''} aria-label="${label}" title="${label}">×</button>`;
  }
  function requestsHTML(){
    const rs=state.requests.filter(r=>!r.deletedAt&&status(r)!=='Delivered'&&(!filters.status||status(r)===filters.status)&&activeRequestLines(r).some(l=>(!filters.poNo||l.poNo===filters.poNo)&&(!filters.sor||l.sor===filters.sor)&&[l.sor,l.sd,l.poNo,l.project,l.model].join(' ').toLowerCase().includes(search.toLowerCase())));
    const refs=(r,k)=>[...new Set(activeRequestLines(r).map(l=>l[k]).filter(Boolean))];
    const refCell=(values,fallback='Not recorded')=>`<span class="ool-request-ref" title="${esc(values.join(', ')||fallback)}">${esc(values[0]||fallback)}${values.length>1?` <span class="ool-request-count">+${values.length-1}</span>`:''}</span>`;
    const widths=[3,14,14,25,6,7,14,17];
    return `<div class="ool-card"><div class="ool-table-wrap"><table class="ool-table ool-request-table"><colgroup>${widths.map(width=>`<col style="width:${width}%">`).join('')}</colgroup><thead><tr>${['','SOR No.','SD No.','Project / PO No.','Models','Total Qty','Total Amount (AED)','Status'].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr class="ool-request-row ${expanded.has(r.id)?'selected':''}" data-expand="${r.id}" tabindex="0"><td>${expanded.has(r.id)?'⌄':'›'}</td><td><strong>${refCell(refs(r,'sor'))}</strong><small>${new Date(r.date).toLocaleDateString('en-GB')}</small></td><td>${refCell(refs(r,'sd'))}</td><td>${refCell(refs(r,'project'))}<small>${refCell(refs(r,'poNo'))}</small></td><td>${activeRequestLines(r).length}</td><td>${activeRequestLines(r).reduce((n,l)=>n+l.qty-(l.cancelled||0),0)}</td><td class="ool-request-amount"><strong>${money(activeRequestLines(r).reduce((n,l)=>n+(l.qty-(l.cancelled||0))*l.priceCents,0))}</strong></td><td class="ool-request-status-cell">${badge(status(r),requestDetails(r))}${deleteButton(r)}</td></tr>${expanded.has(r.id)?`<tr><td colspan="8" class="ool-expansion"><table class="ool-table ool-request-materials"><colgroup><col style="width:50%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:17%"></colgroup><thead><tr><th>Material (Model)</th><th>Requested Qty</th><th>Confirmed Qty</th><th>Delivered Qty</th><th>Status</th></tr></thead><tbody>${activeRequestLines(r).map(l=>{
      const received=requestReceived(l),pending=l.qty-l.confirmed-(l.cancelled||0),activeQty=l.qty-(l.cancelled||0);
      const lineStatus=received===activeQty?'Delivered':l.confirmed===activeQty?'Delivery Confirmed':l.confirmed?'Partially Confirmed':'Delivery Requested';
      return `<tr><td><span class="ool-material-inline" title="${esc(`${l.model} - ${l.poNo} · ${l.sor}`)}"><strong>${esc(l.model)}</strong><small> - ${esc(l.poNo)} · ${esc(l.sor)}</small></span></td><td><strong>${activeQty}</strong></td><td><input class="ool-confirm" aria-label="Confirmed quantity for ${esc(l.model)}" data-request-line="${esc(l.id)}" type="number" min="${received}" max="${activeQty}" value="${l.confirmed}"></td><td>${received}</td><td class="ool-request-status-cell">${badge(lineStatus,[[Math.max(0,l.confirmed-received),'Delivery Confirmed'],[pending,'Delivery Requested'],[received,'Delivered']])}${deleteButton(r,l)}</td></tr>`;
    }).join('')}</tbody></table><div class="ool-expand-footer"><div class="ool-confirmation-summary"><span>Confirmed: <b>${sum(r.lines,'confirmed')}</b> &nbsp; Pending: <b>${sum(r.lines,'qty')-sum(r.lines,'confirmed')-sum(r.lines,'cancelled')}</b></span><label>Delivery Confirmation Date <input type="date" id="date-${esc(r.id)}" value="${esc(r.confirmationDate||today())}"></label></div><div class="ool-confirmation-actions"><button data-follow="${esc(r.id)}">Copy Pending Request</button><button class="ool-primary" data-save-confirm="${esc(r.id)}">Save Confirmation</button></div></div></td></tr>`:''}`).join('')||'<tr><td colspan="8" class="ool-empty">No delivery requests yet. Select available materials in OOL List to prepare one.</td></tr>'}</tbody></table></div><div class="ool-footer">${rs.length} independent delivery requests</div></div>`;
  }
  async function deleteRequest(button){
    const r=state.requests.find(r=>r.id===button.dataset.deleteRequest);if(!r)return;
    const l=button.dataset.deleteLine?r.lines.find(l=>l.id===button.dataset.deleteLine):null;
    const message=l?`Remove ${l.qty-l.confirmed-(l.cancelled||0)} pending units of ${l.model}? This quantity will return to Available.${l.confirmed?' Confirmed quantities will be kept.':''}`:'Delete this delivery request? All its unconfirmed quantities will return to Available.';
    if(!confirm(message))return;button.disabled=true;
    try{await call(l?'delete-request-line':'delete-request',{id:r.id,...(l?{lineId:l.id}:{})});await refresh();}catch(err){if(button.isConnected)button.disabled=false;throw err;}
  }
  function bindSelectAll(all){if(!all)return;const eligible=filtered().filter(l=>l.available>0||l.status==='Awaiting OC');const count=eligible.filter(l=>selected.has(l.id)).length;all.disabled=!eligible.length;all.checked=!!eligible.length&&count===eligible.length;all.indeterminate=count>0&&count<eligible.length;all.onchange=()=>{eligible.forEach(l=>all.checked?selected.add(l.id):selected.delete(l.id));render();};}
  function bind(){bindStatusTooltips();root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;filters.status='';page=1;render();});root.querySelectorAll('[data-filter]').forEach(b=>b.onchange=()=>{filters[b.dataset.filter]=b.type==='checkbox'?b.checked:b.value;page=1;render();});
    root.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(b.dataset.select):selected.delete(b.dataset.select);render();});bindSelectAll(root.querySelector('#oolSelectAll'));
    root.querySelectorAll('[data-project-inline]').forEach(input=>{
      input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();input.blur();}if(e.key==='Escape'){e.preventDefault();input.value=state.lines.find(l=>l.id===input.dataset.projectInline)?.project||'';input.blur();}};
      input.onblur=async()=>{const line=state.lines.find(l=>l.id===input.dataset.projectInline);if(!line)return;const project=input.value.trim();if(project===String(line.project||'')){input.value=line.project||'';return;}input.disabled=true;input.classList.remove('is-error');input.classList.add('is-saving');try{await call('project',{id:line.id,project});await refresh();}catch(err){input.disabled=false;input.classList.remove('is-saving');input.classList.add('is-error');fail(err);}};
    });
    root.onclick=async e=>{const b=e.target.closest('button,[data-expand]');if(!b)return;try{if(b.dataset.deleteRequest){e.stopPropagation();await deleteRequest(b);return;}if(b.dataset.page){page=Number(b.dataset.page);render();}if(b.dataset.expand){expanded.has(b.dataset.expand)?expanded.delete(b.dataset.expand):expanded.add(b.dataset.expand);render();}if(b.dataset.confirm)openOC(b.dataset.confirm);if(b.dataset.po){await showPurchaseOrders('list');openPurchaseOrderViewModal(b.dataset.po);}if(b.dataset.follow){const r=state.requests.find(r=>r.id===b.dataset.follow);deliveryDialog(r.lines.filter(l=>l.qty-l.confirmed-l.cancelled>0).map(l=>({...l,available:l.qty-l.confirmed-l.cancelled,qty:l.qty-l.confirmed-l.cancelled})),r);}if(b.dataset.cancel){if(confirm('Release only the unconfirmed quantities back to Available?')){await call('cancel',{id:b.dataset.cancel});await refresh();}}if(b.dataset.saveConfirm){await busy(b,'Saving…',async()=>{const r=state.requests.find(r=>r.id===b.dataset.saveConfirm);await call('confirmation',{id:r.id,date:root.querySelector('#date-'+r.id).value,lines:activeRequestLines(r).map(l=>({id:l.id,confirmed:Number(root.querySelector(`[data-request-line="${l.id}"]`).value)}))});await refresh();});}const a=b.dataset.ool;if(a==='refresh')await refresh(true);if(a==='oc')openOC();if(a==='delete-lines'){if(!confirm('Delete the selected OOL materials? This removes them from OOL only; the Purchase Order stays unchanged.'))return;b.disabled=true;try{await call('delete-lines',{ids:state.lines.filter(l=>selected.has(l.id)).map(l=>l.id)});selected.clear();await refresh();}finally{if(b.isConnected)b.disabled=false;}return;}if(a==='request')deliveryDialog(state.lines.filter(l=>selected.has(l.id)&&l.available).map(l=>({...l,lineId:l.id,qty:l.available})));if(a==='import')importDialog();if(a==='receipts')receiptDialog();if(a==='audit')auditDialog();}catch(err){fail(err);}};
  }
  function modal(title,sub,body,actions){document.querySelector('.ool-overlay')?.remove();const d=document.createElement('div');d.className='ool-overlay';d.innerHTML=`<section class="ool-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><div><h2>${title}</h2><p>${sub}</p></div><button data-close aria-label="Close">×</button></header><div class="ool-dialog-body">${body}</div><footer><span class="ool-error" role="alert"></span><button data-close>Cancel</button>${actions}</footer></section>`;document.body.append(d);const prev=document.activeElement;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{d.remove();prev?.focus();});d.onkeydown=e=>{if(e.key==='Escape')d.remove();if(e.key==='Tab'){const f=[...d.querySelectorAll('button,input,textarea,select,[contenteditable]')].filter(x=>!x.disabled&&x.getClientRects().length);const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};d.querySelector('input,button')?.focus();return d;}
  function action(d,selector,fn){d.querySelector(selector).onclick=async e=>{d.querySelector('.ool-error').textContent='';try{await busy(e.currentTarget,selector==='#applyImport'?'Applying…':selector==='#oolCommit'?'Requesting…':'Saving…',fn);}catch(err){d.querySelector('.ool-error').textContent=err.message;}};}
  async function copyEmail(e){
    try{if(navigator.clipboard?.write&&window.ClipboardItem){await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([e.html],{type:'text/html'}),'text/plain':new Blob([e.text],{type:'text/plain'})})]);return;}}catch{}
    try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(e.text);return;}}catch{}
    const listener=event=>{event.clipboardData.setData('text/html',e.html);event.clipboardData.setData('text/plain',e.text);event.preventDefault();};document.addEventListener('copy',listener);let copied=false;try{copied=document.execCommand('copy');}finally{document.removeEventListener('copy',listener);}if(!copied)throw Error('Clipboard unavailable. Select and copy the email preview manually.');
  }
  function splitParent(l){
    if(l.confirmedQty||state.requests.some(r=>r.lines.some(x=>x.lineId===l.id))||state.receipts.some(r=>r.allocations.some(a=>a.lineId===l.id)))return null;
    const same=x=>x.id!==l.id&&x.poId===l.poId&&x.poNo===l.poNo&&String(x.model).trim().toUpperCase()===String(l.model).trim().toUpperCase()&&(l.poLineId?x.poLineId===l.poLineId:!!l.sourceKey&&x.sourceKey===l.sourceKey);
    const parent=l.splitFromId?state.lines.find(x=>x.id===l.splitFromId&&same(x)):state.lines.find(x=>same(x)&&l.poOrderedQty);
    return parent&&(l.splitFromId||state.lines.indexOf(parent)<state.lines.indexOf(l))?parent:null;
  }
  async function openOC(poId){if(!state)await refresh();const pendingLines=state.lines.filter(l=>l.confirmedQty<l.orderQty);const groups=[...new Map(pendingLines.map(l=>[l.poId||l.poNo,{id:l.poId||l.poNo,name:l.poNo}])).values()];const chosen=state.lines.find(l=>l.id===poId);poId=chosen?.poId||chosen?.poNo||poId;if(!groups.some(p=>p.id===poId))poId=groups[0]?.id;const d=modal('Verify Order Confirmation','Upload an OC or record an oral confirmation. Confirm only the remaining quantity. Earlier confirmations keep their original document details.',`<div class="ool-oc-toolbar"><label>Purchase Order<select id="ocPO" ${groups.length?'':'disabled'}>${groups.length?groups.map(p=>`<option value="${esc(p.id)}" ${p.id===poId?'selected':''}>${esc(p.name)}</option>`).join(''):'<option value="">No purchase orders awaiting OC</option>'}</select></label><label class="ool-oc-upload">Upload OC <span class="ool-oc-file-types">PDF, image or Excel</span><input id="ocFile" type="file" accept=".pdf,.png,.jpg,.jpeg,.xlsx" ${groups.length?'':'disabled'}></label></div><p class="ool-oc-help">Enter the remaining quantity, SD Document, SOR and unit price for this confirmation, or upload an OC to extract them.</p><div id="ocLines"></div><label>Confirmation notes<textarea id="ocNotes" placeholder="For oral confirmation: contact name and details"></textarea></label>`,'<button class="ool-primary" id="saveOC">Verify & Save OC</button>');let hash='',filename='',attachment;
    d.querySelector('.ool-dialog').classList.add('ool-oc-dialog');
    const title=d.querySelector('header h2'),titleRow=document.createElement('div');titleRow.className='ool-oc-title-row';title.replaceWith(titleRow);titleRow.append(title);titleRow.insertAdjacentHTML('beforeend',`<label class="ool-oc-date">OC Date<input type="date" id="ocDate" value="${today()}"></label>`);
    d.querySelector('#saveOC').disabled=!groups.length;
    const draw=()=>{const lines=state.lines.filter(l=>l.confirmedQty<l.orderQty&&(l.poId||l.poNo)===d.querySelector('#ocPO').value);d.querySelector('#ocLines').innerHTML=`<table class="ool-table"><thead><tr><th>Model</th><th>PO Qty</th><th>Already confirmed</th><th>Total confirmed Qty</th><th>SD Document</th><th>SOR No.</th><th>Unit Price (AED)</th></tr></thead><tbody>${lines.map(l=>`<tr data-oc-line="${l.id}"><td><strong>${esc(l.model)}</strong></td><td>${l.orderQty}<div class="ool-oc-line-actions">${l.orderQty>l.confirmedQty&&l.orderQty>1?`<button type="button" class="ool-link" data-split="${l.id}">Split OC line</button>`:""}${splitParent(l)?`<button type="button" class="ool-link" data-undo-split="${l.id}" title="Merge this unconfirmed quantity back into its original OC line">Undo split</button>`:""}</div></td><td>${l.confirmedQty}</td><td><input data-q type="number" min="0" max="${l.orderQty-l.confirmedQty}" value="${l.orderQty-l.confirmedQty}"></td><td><input data-oc-sd value="" placeholder="SD Document"></td><td><input data-oc-sor value="" placeholder="5S…"></td><td><input data-price type="number" step="0.01" min="0" value="" placeholder="Unit price"></td></tr>`).join('')||'<tr><td colspan="7" class="ool-empty">No materials awaiting OC.</td></tr>'}</tbody></table>`;};draw();d.querySelector('#ocLines').onclick=async e=>{const b=e.target.closest('[data-split],[data-undo-split]');if(!b)return;if(b.dataset.undoSplit){if(!confirm('Merge this unconfirmed split quantity back into its original OC line?'))return;b.disabled=true;try{await call('undo-split',{id:b.dataset.undoSplit});savedSnapshot=false;draw();}catch(err){d.querySelector('.ool-error').textContent=err.message;}finally{if(b.isConnected)b.disabled=false;}return;}const n=prompt('Unconfirmed quantity to track under a separate SD / OC:');if(!n)return;try{await call('split',{id:b.dataset.split,qty:Number(n)});savedSnapshot=false;draw();}catch(err){d.querySelector('.ool-error').textContent=err.message;}};d.querySelector('#ocLines').oninput=e=>{if(e.target.matches('[data-oc-sd],[data-oc-sor]'))e.target.dataset.override='yes';};d.querySelector('#ocPO').onchange=()=>{hash='';filename='';attachment=undefined;d.querySelector('#ocFile').value='';draw();};d.querySelector('#ocFile').onchange=async e=>{try{d.querySelector('.ool-error').textContent='Extracting…';const form=new FormData();form.append('file',e.target.files[0]);const r=await fetch('/api/ool/extract',{method:'POST',body:form});const x=await r.json();if(!r.ok)throw Error(x.error);hash=x.hash;filename=x.filename;attachment=x.attachment;if(x.date)d.querySelector('#ocDate').value=x.date;if(x.sd)d.querySelectorAll('[data-oc-sd]').forEach(i=>{if(!i.value)i.value=x.sd;});if(x.sor)d.querySelectorAll('[data-oc-sor]').forEach(i=>{if(!i.value)i.value=x.sor;});
      const unmatched=[];for(const l of x.lines||[]){const matches=[...d.querySelectorAll('[data-oc-line]')].filter(tr=>state.lines.find(x=>x.id===tr.dataset.ocLine).model===l.model);if(matches.length!==1){unmatched.push(l.model);continue;}matches[0].querySelector('[data-q]').value=l.confirmedQty;matches[0].querySelector('[data-price]').value=l.price??l.priceCents/100;}d.querySelector('.ool-error').textContent=unmatched.length?'Review unmatched or repeated models: '+unmatched.join(', '):'Extraction ready. Verify quantities, references and prices.';}catch(err){d.querySelector('.ool-error').textContent=err.message;}};
    action(d,'#saveOC',async()=>{await call('oc',{quantityMode:'additional',hash,filename,attachment,date:d.querySelector('#ocDate').value,notes:d.querySelector('#ocNotes').value,lines:[...d.querySelectorAll('[data-oc-line]')].map(tr=>({id:tr.dataset.ocLine,confirmedQty:Number(tr.querySelector('[data-q]').value),price:tr.querySelector('[data-price]').value,sd:tr.querySelector('[data-oc-sd]').value,sor:tr.querySelector('[data-oc-sor]').value}))});d.remove();await refresh();});
  }
  function bindContactPicker(d,contacts){
    const picker=d.querySelector('.ool-contact-picker'),input=d.querySelector('#commonContact'),toggle=d.querySelector('#oolContactToggle'),list=d.querySelector('#oolContactOptions');
    let active=-1;
    const highlight=()=>{list.querySelectorAll('[data-contact-index]').forEach((item,i)=>{item.classList.toggle('is-active',i===active);item.setAttribute('aria-selected',String(contacts[i].label===input.value));});if(!list.hidden&&active>=0){input.setAttribute('aria-activedescendant',`ool-contact-option-${active}`);list.querySelector(`[data-contact-index="${active}"]`)?.scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');};
    const open=show=>{list.hidden=!show;input.setAttribute('aria-expanded',String(show));toggle.setAttribute('aria-expanded',String(show));if(show){active=contacts.findIndex(c=>c.label===input.value);if(active<0&&contacts.length)active=0;}highlight();};
    const choose=i=>{if(!contacts[i])return;input.value=contacts[i].label;input.dispatchEvent(new Event('input',{bubbles:true}));open(false);input.focus();input.setSelectionRange(input.value.length,input.value.length);};
    toggle.onclick=()=>{const show=list.hidden;input.focus();open(show);};
    list.onpointerdown=e=>{if(e.target.closest('[data-contact-index]'))e.preventDefault();};
    list.onclick=e=>{const item=e.target.closest('[data-contact-index]');if(item)choose(Number(item.dataset.contactIndex));};
    input.addEventListener('input',()=>{if(!list.hidden)highlight();});
    picker.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();e.stopPropagation();if(list.hidden)open(true);else if(contacts.length){active=(active+(e.key==='ArrowDown'?1:-1)+contacts.length)%contacts.length;highlight();}}else if(e.key==='Enter'&&!list.hidden){e.preventDefault();e.stopPropagation();choose(active);}else if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();open(false);}else if(e.key==='Tab')open(false);};
    picker.addEventListener('focusout',e=>{if(!picker.contains(e.relatedTarget))open(false);});
    d.addEventListener('pointerdown',e=>{if(!picker.contains(e.target))open(false);});
  }
  function deliveryDialog(lines,follow){if(!lines.length)return fail(Error('No pending quantities to request'));const token=uuid();let defaults={};try{defaults=JSON.parse(localStorage.getItem('ool-delivery-'+currentUser.id)||'{}');}catch{}
    const contacts=(state.contacts||[]).filter(c=>c.name?.trim()&&c.contact?.trim()).map(c=>({...c,label:`Mr. ${c.name.replace(/^mr\.?\s*/i,'')} (${c.contact})`}));
    const contactDefault=contacts.find(c=>c.id===currentUser.id)?.label||defaults.contact||'';
    const d=modal(follow?'Pending Delivery Follow-up':'Delivery Request','Prepare delivery request email for selected OOL materials.',`<table class="ool-table ool-selected-materials"><thead><tr><th>Material (Model)</th><th>Available Qty</th><th>Request Qty</th><th>Unit Price (AED)</th><th>Total Amount (AED)</th></tr></thead><tbody>${lines.map((l,i)=>`<tr><td><strong>${esc(l.model)}</strong><small>${esc(l.poNo)} · ${esc(l.sor)}</small></td><td><span class="ool-qty">${l.available}</span></td><td><input data-req="${i}" type="number" min="1" max="${l.available}" step="1" value="${l.qty}" ${follow?'readonly':''}></td><td>${money(l.priceCents)}</td><td data-amount="${i}">${money(l.qty*l.priceCents)}</td></tr>`).join('')}</tbody></table><div id="oolRequestTotal" class="ool-total"></div><div class="ool-form-grid ool-delivery-defaults"><label>Common location<input id="commonLocation" value="${esc(defaults.location||'')}"></label><div class="ool-contact-field"><label for="commonContact">Common contact person</label><div class="ool-contact-picker"><input id="commonContact" type="text" role="combobox" aria-haspopup="listbox" aria-expanded="false" aria-autocomplete="none" aria-controls="oolContactOptions" autocomplete="off" placeholder="Select or type contact details" value="${esc(contactDefault)}"><button id="oolContactToggle" type="button" aria-label="Show all saved contacts" aria-expanded="false" aria-controls="oolContactOptions"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 9 6 6 6-6"/></svg></button><div id="oolContactOptions" role="listbox" aria-label="Saved contact persons" hidden>${contacts.map((c,i)=>`<div id="ool-contact-option-${i}" role="option" aria-selected="${c.label===contactDefault}" data-contact-index="${i}">${esc(c.label)}</div>`).join('')||'<div class="ool-contact-empty">No saved contacts with a number. Type contact details above.</div>'}</div></div></div><label>Delivery date<input type="date" id="commonDate" value="${today()}"></label></div><section class="ool-email"><h3>✉ Email Template Preview</h3><label>Subject<input id="emailSubject" value=""></label><div id="emailIntro" contenteditable="true">Dear team,<br><br>Kindly arrange delivery of Units as per the details below.</div><div class="ool-email-scroll"><table id="oolEmailTable" style="border-collapse:collapse;width:100%;font:12px Arial,sans-serif"><thead><tr>${['Sales Order','Purchase Order','SOR','Material','Net Price from OOL','QTY','Location','Contact Person','Delivery Date'].map((h,i)=>`<th style="border:1px solid #b8beca;padding:8px;background:${i===8?'#f5f6c8':'#f2ead7'};color:#123ab0">${h}</th>`).join('')}</tr></thead><tbody>${lines.map((l,i)=>`<tr>${[l.sd,l.poNo,l.sor,l.model,money(l.priceCents),l.qty,defaults.location||'',contactDefault,today()].map((v,j)=>`<td style="border:1px solid #b8beca;padding:8px;text-align:center" ${j>=6?`contenteditable="true" data-detail="${i}-${j}"`:''} ${j===5?`data-email-qty="${i}"`:''}>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`,`${!follow?'<button id="oolCopy">Copy Email</button><button id="oolImage">Copy Table as Image</button><button class="ool-primary" id="oolCommit">Mark as Requested</button>':'<button id="oolCopy">Copy Follow-up Email</button><button id="oolImage">Copy Table as Image</button>'}`);
    d.querySelector('.ool-dialog').classList.add('ool-delivery-dialog');
    const subtitle=d.querySelector('header p');subtitle.classList.add('ool-delivery-subtitle');subtitle.innerHTML=`<span>Prepare delivery request email for selected OOL materials.</span><span class="ool-request-date">Request Date <strong>${esc(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dubai',day:'2-digit',month:'short',year:'numeric'}).format(new Date()))}</strong></span>`;
    let generatedSubject='';
    const updateSubject=()=>{const input=d.querySelector('#emailSubject'),location=d.querySelector('#commonLocation').value.trim(),projects=[...new Set(lines.map(l=>String(l.project||'').trim()).filter(Boolean))].join(', '),total=money(lines.reduce((n,l)=>n+l.qty*l.priceCents,0));const next=(follow?'Follow-up: ':'')+['Delivery Request',location,projects].filter(Boolean).join(' - ')+' | AED '+total;if(!input.value.trim()||input.value===generatedSubject)input.value=next;generatedSubject=next;};
    const update=()=>{lines.forEach((l,i)=>{l.qty=Number(d.querySelector(`[data-req="${i}"]`).value);d.querySelector(`[data-amount="${i}"]`).textContent=money(l.qty*l.priceCents);d.querySelector(`[data-email-qty="${i}"]`).textContent=l.qty;});d.querySelector('#oolRequestTotal').textContent=`Total Qty: ${sum(lines,'qty')}   |   Total Amount: AED ${money(lines.reduce((n,l)=>n+l.qty*l.priceCents,0))}`;updateSubject();};update();d.querySelectorAll('[data-req]').forEach(x=>x.oninput=update);
    for(const [id,col] of [['commonLocation',6],['commonContact',7],['commonDate',8]])d.querySelector('#'+id).oninput=e=>{d.querySelectorAll(`[data-detail$="-${col}"]`).forEach(c=>{if(!c.dataset.override)c.textContent=e.target.value;});if(id==='commonLocation')updateSubject();};d.querySelectorAll('[data-detail]').forEach(c=>c.oninput=()=>c.dataset.override='yes');
    bindContactPicker(d,contacts);
    const email=()=>({subject:d.querySelector('#emailSubject').value,html:[d.querySelector('#emailIntro'),d.querySelector('#oolEmailTable')].map(x=>x.outerHTML.replace(/contenteditable="true"/g,'')).join('<br>'),text:[d.querySelector('#emailIntro'),d.querySelector('#oolEmailTable')].map(x=>x.innerText).join('\n\n')});
    action(d,'#oolCopy',async()=>{const e=email();await copyEmail(e);if(follow){await call('followup',{id:follow.id,email:e});state=await call();}d.querySelector('.ool-error').textContent='Email copied.';});
    action(d,'#oolImage',async()=>{await copyTableImage(d.querySelector('#oolEmailTable'));if(follow){await call('followup',{id:follow.id,email:email()});state=await call();}d.querySelector('.ool-error').textContent='Table image prepared.';});
    if(!follow)action(d,'#oolCommit',async()=>{update();if(lines.some(l=>!Number.isInteger(l.qty)||l.qty<1||l.qty>l.available))throw Error('Enter whole request quantities within availability');const e=email();await call('request',{token,email:e,lines:lines.map((l,i)=>({lineId:l.lineId,qty:l.qty,location:d.querySelector(`[data-detail="${i}-6"]`).textContent,contact:d.querySelector(`[data-detail="${i}-7"]`).textContent,date:d.querySelector(`[data-detail="${i}-8"]`).textContent}))});try{localStorage.setItem('ool-delivery-'+currentUser.id,JSON.stringify({location:d.querySelector('#commonLocation').value,contact:d.querySelector('#commonContact').value}));}catch{}selected.clear();d.remove();await refresh();});
  }
  async function copyTableImage(table){const rows=[...table.rows].map(r=>[...r.cells].map(c=>c.textContent));const widths=[110,155,100,190,125,60,140,220,120],scale=2,pad=10;const c=document.createElement('canvas');const ctx=c.getContext('2d');ctx.font='14px Arial';const wrap=(text,w)=>{const words=String(text).split(/\s+/),out=[];let line='';for(const word of words){if(ctx.measureText(line+' '+word).width>w && line){out.push(line);line=word;}else line+=(line?' ':'')+word;}out.push(line);return out;};const heights=rows.map(r=>Math.max(42,...r.map((t,i)=>wrap(t,widths[i]-20).length*19+20)));c.width=widths.reduce((a,b)=>a+b,0)*scale;c.height=heights.reduce((a,b)=>a+b,0)*scale;ctx.scale(scale,scale);ctx.font='14px Arial';ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);let y=0;rows.forEach((r,ri)=>{let x=0;r.forEach((t,i)=>{ctx.fillStyle=ri===0?(i===8?'#f5f6c8':'#f2ead7'):'#fff';ctx.fillRect(x,y,widths[i],heights[ri]);ctx.strokeStyle='#b8beca';ctx.strokeRect(x,y,widths[i],heights[ri]);ctx.fillStyle=ri===0?'#123ab0':'#17243b';ctx.font=(ri===0?'bold ':'')+'14px Arial';wrap(t,widths[i]-20).forEach((line,k)=>ctx.fillText(line,x+pad,y+25+k*19));x+=widths[i];});y+=heights[ri];});const blob=await new Promise(r=>c.toBlob(r,'image/png'));try{if(!navigator.clipboard?.write)throw Error();await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);}catch{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='delivery-request.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}
  function importDialog(){const d=modal('Import & Reconcile Excel','Review supplier balances before applying. Existing requests and project overrides are preserved.',`<label>Supplier workbook<input id="importFile" type="file" accept=".xlsx"></label><div id="importPreview" class="ool-import-preview"></div><div id="importWarnings" class="ool-import-warnings" role="alert" hidden></div>`,'<button class="ool-primary" id="applyImport" disabled>Apply reviewed reconciliation</button>');d.querySelector('.ool-dialog').classList.add('ool-import-dialog');d.querySelector('header h2').insertAdjacentHTML('afterend','<span class="ool-import-progress ool-sync-status" role="status" hidden></span>');let preview,uploadSequence=0;d.querySelector('#importFile').onchange=async e=>{const sequence=++uploadSequence;const progress=d.querySelector('.ool-import-progress');progress.hidden=false;progress.textContent='Uploading & checking Excel…';d.querySelector('#importFile').disabled=true;d.querySelector('.ool-error').textContent='';d.querySelector('#importWarnings').hidden=true;d.querySelector('#applyImport').disabled=true;try{const f=new FormData();f.append('file',e.target.files[0]);const r=await fetch('/api/ool/import-preview',{method:'POST',headers:{'X-OOL-View':'compact'},body:f});const result=await r.json();if(sequence!==uploadSequence||!d.isConnected)return;preview=result;if(!r.ok)throw Error(preview.error);d.querySelector('#importPreview').innerHTML=`<table class="ool-table ool-import-table"><colgroup><col style="width:14%"><col style="width:30%"><col style="width:12%"><col style="width:12%"><col style="width:13%"><col style="width:19%"></colgroup><thead><tr><th>SD / SOR</th><th>PO / Model</th><th>Current remaining</th><th>Supplier Open Qty</th><th>Unit price</th><th>Review</th></tr></thead><tbody>${preview.lines.map(l=>{const old=state.lines.find(x=>x.id===l.matchedLineId)||state.lines.find(x=>x.sourceKey===l.sourceKey);const review=l.review||(!old?'New / PO link needs review':old.remaining!==l.confirmedQty?'Quantity differs':old.priceCents!==l.priceCents?'Price differs':'Unchanged');return `<tr class="${review!=='Unchanged'?'ool-import-changed':''} ${l.matchError?'ool-import-conflict':''}"><td>${esc(l.sd)}<small>${esc(l.sor)}</small></td><td><span class="ool-import-reference" title="${esc(l.poNo)}">${esc(l.poNo)}</span><small class="ool-import-reference" title="${esc(l.model+(l.supplierItem?' · Supplier item: '+l.supplierItem:''))}">${esc(l.model)}</small></td><td>${l.currentRemaining??old?.remaining??'New'}</td><td>${l.confirmedQty}</td><td>${money(l.priceCents)}</td><td>${esc(review)}</td></tr>`;}).join('')}</tbody></table>`;const skipped=preview.warnings||[],warningBox=d.querySelector('#importWarnings');warningBox.hidden=!skipped.length;if(skipped.length){const excluded=skipped.reduce((n,w)=>n+(w.amountCents||0),0);warningBox.innerHTML=`<strong>${skipped.length} ${skipped.length===1?'row was':'rows were'} skipped — not included in OOL.</strong><ul>${skipped.map(w=>`<li>Excel row ${esc(w.row)}: <b>${esc(w.model)}</b>${w.qty!==null?` · Qty ${esc(w.qty)}`:''} — ${esc(w.message)}${w.amountCents!==null?` · AED ${money(w.amountCents)} excluded`:''}</li>`).join('')}</ul><span>Known excluded value: <b>AED ${money(excluded)}</b>. Fill the missing details in Excel and upload again to include these rows.</span>`;d.querySelector('.ool-error').textContent=`${skipped.length} incomplete ${skipped.length===1?'row skipped':'rows skipped'} — see the alert below the table.`;}
d.querySelector('#applyImport').disabled=!preview.lines.length||preview.lines.some(l=>l.matchError);if(preview.lines.some(l=>l.matchError)){const conflicts=preview.lines.filter(l=>l.matchError),first=conflicts[0];d.querySelector('.ool-error').textContent=`${conflicts.length} ${conflicts.length===1?'row needs':'rows need'} review: ${first.model} (${first.poNo}).`;d.querySelector('#importPreview').insertAdjacentHTML('afterbegin',`<div class="ool-import-errors" role="alert"><span><strong>${conflicts.length} ${conflicts.length===1?'row needs':'rows need'} review.</strong> Red rows have errors; orange rows are normal changes.</span><button type="button" data-first-import-conflict>Show first conflict</button></div>`);d.querySelector('[data-first-import-conflict]').onclick=()=>d.querySelector('.ool-import-conflict')?.scrollIntoView({behavior:'smooth',block:'center'});}}catch(err){d.querySelector('.ool-error').textContent=err.message;}finally{if(sequence===uploadSequence){progress.hidden=true;d.querySelector('#importFile').disabled=false;}}};action(d,'#applyImport',async()=>{if(!confirm('Apply the reviewed supplier balance changes?'+(preview.warnings?.length?` ${preview.warnings.length} incomplete row(s) will be skipped.`:'')))return;const progress=d.querySelector('.ool-import-progress');progress.hidden=false;progress.textContent='Applying reconciliation…';try{await call('reconcile',preview);}finally{progress.hidden=true;}d.remove();await refresh();});}
  function receiptDialog(){const sources=(state.sources||[]).filter(x=>x.lines.some((l,i)=>l.qty>state.receipts.filter(r=>r.sourceId===x.id).flatMap(r=>r.allocations).filter(a=>a.sourceIndex===i).reduce((n,a)=>n+a.qty,0)));const d=modal('Match Received Materials','Allocate an existing warehouse receipt or direct project delivery to OOL. This does not add warehouse stock again.',`<label>Confirmed receipt<select id="receiptSource"><option value="">Select receipt…</option>${sources.map(x=>`<option value="${esc(x.id)}">${esc(x.kind+' · '+x.label)}</option>`).join('')}</select></label><div id="receiptMatches"></div>`,'<button class="ool-primary" id="saveReceipt">Confirm OOL Receipt</button>');d.querySelector('#receiptSource').onchange=e=>{const s=sources.find(x=>x.id===e.target.value);d.querySelector('#receiptMatches').innerHTML=s?`<table class="ool-table"><thead><tr><th>Receipt model / SD</th><th>Received Qty</th><th>OOL line</th><th>Allocate Qty</th></tr></thead><tbody>${s.lines.map((l,i)=>{const allocated=state.receipts.filter(r=>r.sourceId===s.id).flatMap(r=>r.allocations).filter(a=>a.sourceIndex===i).reduce((n,a)=>n+a.qty,0);l={...l,qty:l.qty-allocated};const candidates=state.lines.filter(x=>x.remaining&&x.model===l.model&&x.sd===l.sd&&l.sd);return `<tr data-source-row="${i}"><td>${esc(l.model)}<small>${esc(l.sd||'SD missing: enter during receipt verification')}</small></td><td>${l.qty}</td><td><select data-match><option value="">Do not allocate</option>${candidates.map(x=>`<option value="${x.id}" ${candidates.length===1?'selected':''}>${esc(x.poNo+' · '+x.sor+' · '+x.project)} (${x.remaining})</option>`).join('')}</select></td><td><input data-receive type="number" min="0" max="${l.qty}" value="${candidates.length===1?Math.min(l.qty,candidates[0].remaining):0}"></td></tr>`;}).join('')}</tbody></table><p class="ool-note">Review matches before confirming. Multiple matches require an explicit choice.</p>`:'';};action(d,'#saveReceipt',async()=>{const allocations=[...d.querySelectorAll('[data-source-row]')].filter(tr=>tr.querySelector('[data-match]').value&&Number(tr.querySelector('input').value)>0).map(tr=>({sourceIndex:Number(tr.dataset.sourceRow),lineId:tr.querySelector('[data-match]').value,qty:Number(tr.querySelector('input').value)}));await call('receipt',{sourceId:d.querySelector('#receiptSource').value,allocations});d.remove();await refresh();});}
  function auditDialog(){modal('Recent Activity','Recent OOL updates and delivery activity.',`${state.audit.slice(-50).reverse().map(a=>`<p>${esc(a.action)} · ${esc(a.userName||a.userId||'')} · ${new Date(a.at||'').toLocaleString('en-GB')}</p>`).join('')||'<p>No recent activity.</p>'}`,'');}
  async function reviewReceipt(sourceId){try{state=await call();receiptDialog();const s=document.querySelector('.ool-overlay #receiptSource');s.value=sourceId;s.dispatchEvent(new Event('change'));}catch(e){fail(e);}}
  return {mount,openOC,reviewReceipt};
})();
